package com.alibaba.mnnllm.android.utils

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertSame
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Before
import org.junit.Test
import java.io.ByteArrayInputStream
import java.io.File
import java.io.IOException
import java.io.InputStream
import java.nio.file.Files
import java.util.concurrent.CancellationException

/** Pure file I/O tests: generated bytes only, with test artifacts retained under build/. */
class AttachmentFileCopyTest {
    private lateinit var testDir: File

    @Before
    fun setUp() {
        val root = File(System.getProperty("mnn.attachmentTestDir")
            ?: File(System.getProperty("user.dir"), "build/attachment-copy-tests").absolutePath)
        check(root.isDirectory || root.mkdirs())
        testDir = Files.createTempDirectory(root.toPath(), "copy-").toFile()
    }

    private fun destination() = File(testDir, "nested/attachment.bin")

    @Test
    fun `normal stream copies every byte across buffer boundaries and closes`() {
        val bytes = ByteArray(10037) { (it % 251).toByte() }
        var closed = false
        val stream = object : ByteArrayInputStream(bytes) {
            override fun close() {
                closed = true
                super.close()
            }
        }
        val target = destination()
        val result = FileUtils.copyInputStreamToPath(target.absolutePath) { stream }
        assertEquals(target, result)
        assertArrayEquals(bytes, result.readBytes())
        assertTrue(closed)
    }

    @Test
    fun `empty readable stream is not the same as a missing stream`() {
        val result = FileUtils.copyInputStreamToPath(destination().absolutePath) {
            ByteArrayInputStream(byteArrayOf())
        }
        assertTrue(result.isFile)
        assertEquals(0L, result.length())
    }

    @Test
    fun `null provider stream becomes io exception without creating a destination`() {
        val target = destination()
        val error = expectFailure(IOException::class.java) {
            FileUtils.copyInputStreamToPath(target.absolutePath) { null }
        }
        assertTrue(error.message.orEmpty().contains("InputStream"))
        assertFalse(target.exists())
    }

    @Test
    fun `provider io and security failures propagate unchanged`() {
        for (error in listOf(IOException("provider failed"), SecurityException("permission revoked"))) {
            val target = destination()
            val actual = expectFailure(error.javaClass) {
                FileUtils.copyInputStreamToPath(target.absolutePath) { throw error }
            }
            assertSame(error, actual)
            assertFalse(target.exists())
        }
    }

    @Test
    fun `io or security error while reading closes input and does not return success`() {
        for (error in listOf(IOException("read failed"), SecurityException("access revoked during read"))) {
            var closed = false
            val stream = object : InputStream() {
                override fun read(): Int = throw error
                override fun close() { closed = true }
            }
            val actual = expectFailure(error.javaClass) {
                FileUtils.copyInputStreamToPath(destination().absolutePath) { stream }
            }
            assertSame(error, actual)
            assertTrue(closed)
        }
    }

    @Test
    fun `destination open failure still closes the provider stream`() {
        var closed = false
        val stream = object : ByteArrayInputStream(byteArrayOf(1, 2, 3)) {
            override fun close() { closed = true }
        }
        // A directory cannot be opened as an output file, independent of host permissions.
        expectFailure(IOException::class.java) {
            FileUtils.copyInputStreamToPath(testDir.absolutePath) { stream }
        }
        assertTrue(closed)
    }

    @Test
    fun `close failure is not reported as successful copy`() {
        val error = IOException("provider close failed")
        val stream = object : ByteArrayInputStream(byteArrayOf(1, 2, 3)) {
            override fun close() { throw error }
        }
        val actual = expectFailure(IOException::class.java) {
            FileUtils.copyInputStreamToPath(destination().absolutePath) { stream }
        }
        assertSame(error, actual)
    }

    @Test
    fun `cancellation during read propagates after input cleanup`() {
        val error = CancellationException("cancelled")
        var closed = false
        val stream = object : InputStream() {
            override fun read(): Int = throw error
            override fun close() { closed = true }
        }
        val actual = expectFailure(CancellationException::class.java) {
            FileUtils.copyInputStreamToPath(destination().absolutePath) { stream }
        }
        assertSame(error, actual)
        assertTrue(closed)
    }

    @Test
    fun `provider open cancellation is not converted into io failure`() {
        val error = CancellationException("cancelled")
        val actual = expectFailure(CancellationException::class.java) {
            FileUtils.copyInputStreamToPath(destination().absolutePath) { throw error }
        }
        assertSame(error, actual)
    }

    private fun <T : Exception> expectFailure(type: Class<T>, action: () -> Unit): T {
        try {
            action()
        } catch (error: Exception) {
            if (!type.isInstance(error)) throw error
            return type.cast(error)
        }
        fail("Expected ${type.simpleName}")
        throw AssertionError("unreachable")
    }
}
